function onFlashLoan(address initiator, address token, uint256 amount, uint256 fee, bytes calldata data) external override returns(bytes32) {
        require(msg.sender == address(lender), "FlashBorrower: Untrusted lender");
        (Action action) = abi.decode(data, (Action)); // Use this to unpack arbitrary data
        flashInitiator = initiator;
        flashToken = token;
        flashAmount = amount;
        flashFee = fee;
        if (action == Action.NORMAL) {
            flashBalance = IERC20(token).balanceOf(address(this));
        } else if (action == Action.TRANSFER) {
            flashBalance = IERC20(token).balanceOf(address(this));
            IERC20(token).transfer(address(lender), amount + fee);
        } else if (action == Action.STEAL) {
            IERC20(token).transfer(address(0), amount);
        } else if (action == Action.REENTER) {    
            flashBorrow(token, amount * 2, Action.NORMAL);
        }
        return keccak256("ERC3156FlashBorrower.onFlashLoan");
    }

function flashBorrow(address token, uint256 amount, Action action) public {
        bytes memory data = abi.encode(action);
        uint256 allowance = IERC20(token).allowance(address(this), address(lender));
        IERC20(token).approve(address(lender), allowance + amount + lender.flashFee(token, amount));
        lender.flashLoan(this, token, amount, data);
    }

function setSource(bytes6 baseId, IERC20Metadata base, bytes6 quoteId, IERC20Metadata quote, address source)
        external auth
    {
        sources[baseId][quoteId] = Source({
            source: source,
            baseDecimals: base.decimals(),
            quoteDecimals: quote.decimals(),
            inverse: false
        });
        emit SourceSet(baseId, base, quoteId, quote, source);

        if (baseId != quoteId) {
            sources[quoteId][baseId] = Source({
                source: source,
                baseDecimals: quote.decimals(), // We are reversing the base and the quote
                quoteDecimals: base.decimals(),
                inverse: true
            });
            emit SourceSet(quoteId, quote, baseId, base, source);
        }
    }

function _peek(bytes6 baseId, bytes6 quoteId, uint256 amountBase)
        private view
        returns (uint amountQuote, uint updateTime)
    {
        int price;
        uint80 roundId;
        uint80 answeredInRound;
        Source memory source = sources[baseId][quoteId];
        require (source.source != address(0), "Source not found");
        (roundId, price,, updateTime, answeredInRound) = AggregatorV3Interface(source.source).latestRoundData();
        require(price > 0, "Chainlink price <= 0");
        require(updateTime != 0, "Incomplete round");
        require(answeredInRound >= roundId, "Stale price");
        if (source.inverse == true) {
            // ETH/USDC: 1 ETH (*10^18) * (1^6)/(286253688799857 ETH per USDC) = 3493404763 USDC wei
            amountQuote = amountBase * (10 ** source.quoteDecimals) / uint(price);
        } else {
            // USDC/ETH: 3000 USDC (*10^6) * 286253688799857 ETH per USDC / 10^6 = 858761066399571000 ETH wei
            amountQuote = amountBase * uint(price) / (10 ** source.baseDecimals);
        }  
    }

function _peek(bytes6 base, bytes6 kind) private view returns (uint accumulator, uint updateTime) {
        address source = sources[base][kind];
        require (source != address(0), "Source not found");

        if (kind == RATE.b6()) accumulator = CTokenInterface(source).borrowIndex();
        else if (kind == CHI.b6()) accumulator = CTokenInterface(source).exchangeRateStored();
        else revert("Unknown oracle type");

        require(accumulator > 0, "Compound accumulator is zero");

        updateTime = block.timestamp;
    }

function setSource(bytes6 cTokenId, bytes6 underlyingId, CTokenInterface cToken)
        external auth
    {
        IERC20Metadata underlying = IERC20Metadata(cToken.underlying());
        uint8 underlyingDecimals = underlying.decimals();
        uint8 cTokenDecimals = underlyingDecimals + 10; // https://compound.finance/docs/ctokens#exchange-rate
        sources[cTokenId][underlyingId] = Source({
            source: cToken,
            baseDecimals: cTokenDecimals,
            quoteDecimals: underlyingDecimals,
            inverse: false
        });
        emit SourceSet(cTokenId, underlyingId, cToken);

        sources[underlyingId][cTokenId] = Source({
            source: cToken,
            baseDecimals: underlyingDecimals, // We are reversing the base and the quote
            quoteDecimals: cTokenDecimals,
            inverse: true
        });
        emit SourceSet(underlyingId, cTokenId, cToken);
    }

function peek(bytes32 base, bytes32 quote, uint256 amountBase)
        external view virtual override
        returns (uint256 amountQuote, uint256 updateTime)
    {
        Source memory source = sources[base.b6()][quote.b6()];
        require (source.source != CTokenInterface(address(0)), "Source not found");

        uint256 price = source.source.exchangeRateStored();
        require(price > 0, "Compound price is zero");

        if (source.inverse == true) {
            // ETH/USDC: 1 ETH (*10^18) * (1^6)/(286253688799857 ETH per USDC) = 3493404763 USDC wei
            amountQuote = amountBase * (10 ** source.quoteDecimals) / uint(price);
        } else {
            // USDC/ETH: 3000 USDC (*10^6) * 286253688799857 ETH per USDC / 10^6 = 858761066399571000 ETH wei
            amountQuote = uint(price) * amountBase / (10 ** source.baseDecimals);
        }
        updateTime = block.timestamp; // TODO: We should get the timestamp
    }

function get(bytes32 base, bytes32 quote, uint256 amountBase)
        external virtual override
        returns (uint256 amountQuote, uint256 updateTime)
    {
        Source memory source = sources[base.b6()][quote.b6()];
        require (source.source != CTokenInterface(address(0)), "Source not found");

        uint256 price = source.source.exchangeRateCurrent();
        require(price > 0, "Compound price is zero");

        if (source.inverse == true) {
            // USDC/cUSDC: 1 USDC (*10^6) * (1^16)/(x USDC per cUSDC) = y cUSDC wei
            amountQuote = amountBase * (10 ** source.quoteDecimals) / uint(price);
        } else {
            // cUSDC/USDC: 3000 cUSDC (*10^18) * x USDC per cUSDC / 10^16 = y USDC wei
            amountQuote = amountBase * uint(price) / (10 ** source.baseDecimals);
        }  
        updateTime = block.timestamp; // TODO: We should get the timestamp
    }

function _peek(bytes6 base, bytes6 quote, uint256 amountBase, uint256 updateTimeIn)
        private view
        returns (uint amountQuote, uint updateTimeOut)
    {
        IOracle source = sources[base][quote];
        require (address(source) != address(0), "Source not found");
        (amountQuote, updateTimeOut) = source.peek(base, quote, amountBase);
        updateTimeOut = (updateTimeOut < updateTimeIn) ? updateTimeOut : updateTimeIn;                 // Take the oldest update time
    }

function _get(bytes6 base, bytes6 quote, uint256 amountBase, uint256 updateTimeIn)
        private
        returns (uint amountQuote, uint updateTimeOut)
    {
        IOracle source = sources[base][quote];
        require (address(source) != address(0), "Source not found");
        (amountQuote, updateTimeOut) = source.get(base, quote, amountBase);
        updateTimeOut = (updateTimeOut < updateTimeIn) ? updateTimeOut : updateTimeIn;                 // Take the oldest update time
    }

function _peek(bytes6 base, bytes6 quote, uint256 amount)
        private view
        returns (uint256 value, uint256 updateTime)
    {
        Source memory source = sources[base][quote];
        SourceData memory sourceData;
        require(source.source != address(0), "Source not found");
        sourceData = sourcesData[source.source];
        if (source.inverse) {
            value = UniswapV3OracleLibraryMock.consult(sourceData.factory, sourceData.quoteToken, sourceData.baseToken, sourceData.fee, amount, secondsAgo);
        } else {
            value = UniswapV3OracleLibraryMock.consult(sourceData.factory, sourceData.baseToken, sourceData.quoteToken, sourceData.fee, amount, secondsAgo);
        }
        updateTime = block.timestamp - secondsAgo;
    }

function _setSource(bytes6 base, bytes6 quote, address source) internal {
        sources[base][quote] = Source(source, false);
        sources[quote][base] = Source(source, true);
        sourcesData[source] = SourceData(
            IUniswapV3PoolImmutables(source).factory(),
            IUniswapV3PoolImmutables(source).token0(),
            IUniswapV3PoolImmutables(source).token1(),
            IUniswapV3PoolImmutables(source).fee()
        );
        emit SourceSet(base, quote, source);
        emit SourceSet(quote, base, source);
    }

function priceMin(string calldata symbol) external returns (uint256 price) {
        MixConfig storage config = configs[keccak256(abi.encodePacked(symbol))];
        uint256 ep;
        uint256 p; //holder variables
        price = MAX_INT;
        if (config.ethOracles.length > 0) {
            ep = MAX_INT;
            for (uint256 i = 0; i < config.ethOracles.length; i++) {
                p = IEthUsdOracle(config.ethOracles[i]).tokEthPrice(symbol);
                if (ep > p) {
                    ep = p;
                }
            }
            price = ep;
            ep = MAX_INT;
            for (uint256 i = 0; i < ethUsdOracles.length; i++) {
                p = IEthUsdOracle(ethUsdOracles[i]).ethUsdPrice();
                if (ep > p) {
                    ep = p;
                }
            }
            if (price != MAX_INT && ep != MAX_INT) {
                // tokEthPrice has precision of 8 which ethUsdPrice has precision of 6
                // we want precision of 8
                price = (price * ep) / 1e6;
            }
        }

        if (config.usdOracles.length > 0) {
            for (uint256 i = 0; i < config.usdOracles.length; i++) {
                // upscale by 2 since price oracles are precision 6
                p = IPriceOracle(config.usdOracles[i]).price(symbol) * 1e2;
                if (price > p) {
                    price = p;
                }
            }
        }
        require(price < maxDrift, "Price exceeds max value.");
        require(price > minDrift, "Price lower than min value.");
        require(
            price != MAX_INT,
            "None of our oracles returned a valid min price!"
        );
    }

function priceMax(string calldata symbol) external returns (uint256 price) {
        MixConfig storage config = configs[keccak256(abi.encodePacked(symbol))];
        uint256 ep;
        uint256 p; //holder variables
        price = 0;
        if (config.ethOracles.length > 0) {
            ep = 0;
            for (uint256 i = 0; i < config.ethOracles.length; i++) {
                p = IEthUsdOracle(config.ethOracles[i]).tokEthPrice(symbol);
                if (ep < p) {
                    ep = p;
                }
            }
            price = ep;
            ep = 0;
            for (uint256 i = 0; i < ethUsdOracles.length; i++) {
                p = IEthUsdOracle(ethUsdOracles[i]).ethUsdPrice();
                if (ep < p) {
                    ep = p;
                }
            }
            if (price != 0 && ep != 0) {
                // tokEthPrice has precision of 8 which ethUsdPrice has precision of 6
                // we want precision of 8
                price = (price * ep) / 1e6;
            }
        }

        if (config.usdOracles.length > 0) {
            for (uint256 i = 0; i < config.usdOracles.length; i++) {
                // upscale by 2 since price oracles are precision 6
                p = IPriceOracle(config.usdOracles[i]).price(symbol) * 1e2;
                if (price < p) {
                    price = p;
                }
            }
        }

        require(price < maxDrift, "Price above max value.");
        require(price > minDrift, "Price below min value.");
        require(price != 0, "None of our oracles returned a valid max price!");
    }

