function pendingReward(address _user) external view returns (uint256) {
        UserInfo storage user = userInfo[_user];
        if (rewardPerBlock == 0) {
            return 0;
        }
        uint256 lpSupply = lpToken.balanceOf(address(this));
        if (block.number <= lastRewardBlock || lpSupply == 0) {
            return 0;
        }
        return
            user
                .amount
                .mul(
                    accMintPerShare.add(
                        block
                            .number
                            .sub(lastRewardBlock)
                            .mul(rewardPerBlock)
                            .mul(1e12)
                            .div(lpSupply)
                    )
                )
                .div(1e12)
