function getCurrentPrice(
        RebalancingLibrary.AuctionPriceParameters memory _auctionPriceParameters
    )
        public
        view
        returns (uint256, uint256)
    {
        // Calculate how much time has elapsed since start of auction
        uint256 elapsed = block.timestamp.sub(_auctionPriceParameters.auctionStartTime);

        // Initialize numerator and denominator
        uint256 priceNumerator = _auctionPriceParameters.auctionPivotPrice;
        uint256 currentPriceDivisor = priceDivisor;

        // Determine the auctionStartPrice based on if it should be self-defined
        uint256 auctionStartPrice = 0;
        if (usesStartPrice) {
            auctionStartPrice = _auctionPriceParameters.auctionStartPrice;
        }

        /*
         * This price curve can be broken down into three stages, 1) set up to allow a portion where managers
         * have control over the cadence of the auction, and then two more stages that are used to enforce finality
         * to the auction. The auction price, p(x), is defined by:
         *
         * p(x) = (priceNumerator/priceDivisor
         *
         * In each stage either the priceNumerator or priceDivisor is manipulated to change p(x).The curve shape
         * in each stage is defined below.
         *
         * 1) Managers have the greatest control over stage 1. Here they define a linear curve that starts at zero
         * and terminates at the passed pivot price. The length of time it takes for the auction to reach the pivot
         * price is defined by the manager too, thus resulting in the following equation for the slope of the line:
         *
         * PriceNumerator(x) = auctionStartPrice + (auctionPivotPrice-auctionStartPrice)*(x/auctionTimeToPivot),
         * where x is amount of time from auction start
         *
         * 2) Stage 2 the protocol takes over to attempt to hasten/guarantee finality, this unfortunately decreases
         * the granularity of the auction price changes. In this stage the PriceNumerator remains fixed at the
         * auctionPivotPrice. However, the priceDivisor decays at a rate equivalent to 0.1% of the ORIGINAL
         * priceDivisor every 30 secs. This leads to the following function relative to time:
         *
         * PriceDenominator(x) = priceDivisor-(0.01*priceDivisor*((x-auctionTimeToPivot)/30)), where x is amount
         * of time from auction start.
         *
         * Since we are decaying the denominator the price curve takes on the shape of e^x. Because of the limitations
         * of integer math the denominator can only be decayed to 1. Hence in order to maintain simplicity in calculations
         * there is a third segment defined below.
         *
         * 3) The third segment is a simple linear calculation that changes the priceNumerator at the rate of the pivot
         * price every 30 seconds and fixes the priceDivisor at 1:
         *
         * PriceNumerator(x) = auctionPivotPrice + auctionPivotPrice*(x-auctionTimeToPivot-30000), where x is amount of
         * time from auction start and 30000 represents the amount of time spent in Stage 2
         */

        // If time hasn't passed to pivot use the user-defined curve
        if (elapsed <= _auctionPriceParameters.auctionTimeToPivot) {
            // Calculate the priceNumerator as a linear function of time between _auctionStartPrice and
            // _auctionPivotPrice
            uint256 linearPriceDifference = _auctionPriceParameters.auctionPivotPrice.sub(auctionStartPrice);
            priceNumerator = auctionStartPrice.add(
                elapsed.mul(linearPriceDifference).div(_auctionPriceParameters.auctionTimeToPivot)
            );
        } else {
            // Calculate how many 30 second increments have passed since pivot was reached
            uint256 thirtySecondPeriods = elapsed
                .sub(_auctionPriceParameters.auctionTimeToPivot)
                .div(THIRTY_SECONDS);

            // Because after 1000 thirtySecondPeriods the priceDivisor would be 0 (causes revert)
            if (thirtySecondPeriods < MAX_30_SECOND_PERIODS) {
                // Calculate new denominator where the denominator decays at a rate of 0.1% of the ORIGINAL
                // priceDivisor per time increment (hence divide by 1000)
                currentPriceDivisor = priceDivisor
                    .sub(thirtySecondPeriods
                        .mul(priceDivisor)
                        .div(MAX_30_SECOND_PERIODS)
                    );
            } else {
                // Once denominator has fully decayed, fix it at 1
                currentPriceDivisor = 1;

                // Now priceNumerator just changes linearly, but with slope equal to the pivot price
                priceNumerator = _auctionPriceParameters.auctionPivotPrice.add(
                    _auctionPriceParameters.auctionPivotPrice.mul(thirtySecondPeriods.sub(MAX_30_SECOND_PERIODS))
                );
            }
        }

        return (priceNumerator, currentPriceDivisor);
    }

function propose(
        address _rebalancingSetTokenAddress
    )
        external
    {
        // Create interface to interact with RebalancingSetToken
        IRebalancingSetToken rebalancingSetInterface = IRebalancingSetToken(_rebalancingSetTokenAddress);

        ManagerLibrary.validateManagerPropose(rebalancingSetInterface);

        // Get price data
        uint256 ethPrice = ManagerLibrary.queryPriceData(ethPriceFeed);

        // Require that allocation has changed sufficiently enough to justify rebalance
        uint256 currentSetDollarAmount = checkSufficientAllocationChange(
            ethPrice,
            rebalancingSetInterface.currentSet()
        );

        // Create new Set Token that collateralizes Rebalancing Set Token
        (
            address nextSetAddress,
            uint256 nextSetDollarAmount
        ) = createNewAllocationSetToken(
            ethPrice
        );

        // Calculate the auctionStartPrice and auctionPivotPrice of rebalance auction using dollar value
        // of both the current and nextSet
        (
            uint256 auctionStartPrice,
            uint256 auctionPivotPrice
        ) = ManagerLibrary.calculateAuctionPriceParameters(
            currentSetDollarAmount,
            nextSetDollarAmount,
            AUCTION_LIB_PRICE_DIVISOR,
            auctionTimeToPivot
        );

        // Propose new allocation to Rebalancing Set Token
        rebalancingSetInterface.propose(
            nextSetAddress,
            auctionLibrary,
            auctionTimeToPivot,
            auctionStartPrice,
            auctionPivotPrice
        );

        emit LogManagerProposal(
            ethPrice
        );
    }

function checkSufficientAllocationChange(
        uint256 _ethPrice,
        address _currentSetAddress
    )
        private
        view
        returns (uint256)
    {
        // Create current set interface
        ISetToken currentSetTokenInterface = ISetToken(_currentSetAddress);

        // Get naturalUnit and units of currentSet
        uint256 currentSetNaturalUnit = currentSetTokenInterface.naturalUnit();
        uint256[] memory currentSetUnits = currentSetTokenInterface.getUnits();

        // Calculate dai dollar value in currentSet (in cents)
        uint256 daiDollarAmount = ManagerLibrary.calculateTokenAllocationAmountUSD(
            DAI_PRICE,
            currentSetNaturalUnit,
            currentSetUnits[0],
            DAI_DECIMALS
        );

        uint256[] memory assetPrices = new uint256[](2);
        assetPrices[0] = DAI_PRICE;
        assetPrices[1] = _ethPrice;

        uint256[] memory assetDecimals = new uint256[](2);
        assetDecimals[0] = DAI_DECIMALS;
        assetDecimals[1] = ETH_DECIMALS;

        uint256 currentSetDollarAmount = ManagerLibrary.calculateSetTokenDollarValue(
            assetPrices,
            currentSetNaturalUnit,
            currentSetUnits,
            assetDecimals
        );

        // Require that the allocation has changed enough to trigger buy or sell
        require(
            daiDollarAmount.mul(100).div(currentSetDollarAmount) >= minimumUpperThreshold ||
            daiDollarAmount.mul(100).div(currentSetDollarAmount) < maximumLowerThreshold,
            "RebalancingTokenManager.proposeNewRebalance: Allocation must be further away from 50 percent"
        );

        return currentSetDollarAmount;
    }

function createNewAllocationSetToken(
        uint256 _ethPrice
    )
        private
        returns (address, uint256)
    {
        // Calculate the nextSet units and naturalUnit, determine dollar value of nextSet
        (
            uint256 nextSetNaturalUnit,
            uint256 nextSetDollarAmount,
            uint256[] memory nextSetUnits
        ) = calculateNextSetUnits(
            _ethPrice
        );

        // Create static components array
        address[] memory nextSetComponents = new address[](2);
        nextSetComponents[0] = daiAddress;
        nextSetComponents[1] = ethAddress;

        // Create the nextSetToken contract that collateralized the Rebalancing Set Token once rebalance
        // is finished
        address nextSetAddress = ICore(coreAddress).createSet(
            setTokenFactory,
            nextSetComponents,
            nextSetUnits,
            nextSetNaturalUnit,
            bytes32("DAIETH"),
            bytes32("DAIETH"),
            ""
        );

        return (nextSetAddress, nextSetDollarAmount);
    }

function calculateNextSetUnits(
        uint256 _ethPrice
    )
        private
        returns (uint256, uint256, uint256[] memory)
    {
        // Initialize set token parameters
        uint256[] memory nextSetUnits = new uint256[](2);
        uint256 nextSetNaturalUnit = PRICE_PRECISION;

        if (_ethPrice >= DAI_PRICE) {
            // Dai nextSetUnits is equal the USD Ethereum price
            uint256 daiUnits = _ethPrice.mul(PRICE_PRECISION).div(DAI_PRICE);

            // Create unit array and define natural unit
            nextSetUnits[0] = daiUnits.mul(daiMultiplier);
            nextSetUnits[1] = ethMultiplier.mul(PRICE_PRECISION);          
        } else {
            // Calculate dai nextSetUnits as (daiPrice/ethPrice)*100. 100 is used to add 
            // precision.
            uint256 ethDaiPrice = DAI_PRICE.mul(PRICE_PRECISION).div(_ethPrice);

            // Create unit array and define natural unit
            nextSetUnits[0] = daiMultiplier.mul(PRICE_PRECISION); 
            nextSetUnits[1] = ethDaiPrice.mul(ethMultiplier);         
        }

        uint256[] memory assetPrices = new uint256[](2);
        assetPrices[0] = DAI_PRICE;
        assetPrices[1] = _ethPrice;

        uint256[] memory assetDecimals = new uint256[](2);
        assetDecimals[0] = DAI_DECIMALS;
        assetDecimals[1] = ETH_DECIMALS;

        uint256 nextSetDollarAmount = ManagerLibrary.calculateSetTokenDollarValue(
            assetPrices,
            nextSetNaturalUnit,
            nextSetUnits,
            assetDecimals
        );

        return (nextSetNaturalUnit, nextSetDollarAmount, nextSetUnits);
    }

