function _dfsBuy(
        ExchangeData memory _exchangeData,
        address _from,
        address _to,
        uint256 _fee
    ) internal returns (uint256) {
         // if we set srcAmount to max, take the whole proxy balance
        if (_exchangeData.srcAmount == type(uint256).max) {
