            msg.sender,
            "DfsBuy",
            abi.encode(
                wrapper,
                _exchangeData.srcAddr,
                _exchangeData.destAddr,
                amountBought,
                _exchangeData.destAmount,
                _fee
            )
        );

        return amountBought;
    }

