function _uniSupply(UniSupplyData memory _uniData) internal returns (uint256) {
        // fetch tokens from the address
        _uniData.tokenA.pullTokens(_uniData.from, _uniData.amountADesired);
        _uniData.tokenB.pullTokens(_uniData.from, _uniData.amountBDesired);

        // approve router so it can pull tokens
        _uniData.tokenA.approveToken(address(router), _uniData.amountADesired);
        _uniData.tokenB.approveToken(address(router), _uniData.amountBDesired);

        // add liq. and get info how much we put in
        (uint256 amountA, uint256 amountB, uint256 liqAmount) = _addLiquidity(_uniData);

        // send leftovers
        _uniData.tokenA.withdrawTokens(_uniData.to, (_uniData.amountADesired - amountA));
        _uniData.tokenB.withdrawTokens(_uniData.to, (_uniData.amountBDesired - amountB));

        logger.Log(
            address(this),
            msg.sender,
            "UniSupply",
            abi.encode(_uniData, amountA, amountB, liqAmount)
        );

        return liqAmount;
    }

function _addLiquidity(UniSupplyData memory _uniData)
        internal
        returns (
            uint256 amountA,
            uint256 amountB,
            uint256 liqAmount
        )
    {
        (amountA, amountB, liqAmount) = router.addLiquidity(
            _uniData.tokenA,
            _uniData.tokenB,
            _uniData.amountADesired,
            _uniData.amountBDesired,
            _uniData.amountAMin,
            _uniData.amountBMin,
            _uniData.to,
            _uniData.deadline
        );
    }

function _uniWithdraw(UniWithdrawData memory _uniData) internal returns (uint256) {
        address lpTokenAddr = factory.getPair(_uniData.tokenA, _uniData.tokenB);

        lpTokenAddr.pullTokens(_uniData.from, _uniData.liquidity);
        lpTokenAddr.approveToken(address(router), _uniData.liquidity);

        // withdraw liq. and get info how much we got out
        (uint256 amountA, uint256 amountB) = _withdrawLiquidity(_uniData);

        logger.Log(
            address(this),
            msg.sender,
            "UniWithdraw",
            abi.encode(_uniData, amountA, amountB)
        );

        return _uniData.liquidity;
    }

function _withdrawLiquidity(UniWithdrawData memory _uniData)
        internal
        returns (uint256 amountA, uint256 amountB)
    {
        (amountA, amountB) = router.removeLiquidity(
            _uniData.tokenA,
            _uniData.tokenB,
            _uniData.liquidity,
            _uniData.amountAMin,
            _uniData.amountBMin,
            _uniData.to,
            _uniData.deadline
        );
    }

