        external
        returns (uint256)
    {
        uint256 _shares = (_amount * 1e18) / pricePerShare(); // calculate shares
        IERC20(token).transferFrom(msg.sender, address(this), _amount); // pull deposit from sender
        _mint(destination, _shares); // mint shares for sender
        return _shares;
    }

function withdraw(
        uint256 _shares,
        address destination,
        uint256
    ) external returns (uint256) {
        uint256 _amount = (_shares * pricePerShare()) / 1e18;
        _burn(msg.sender, _shares);
        IERC20(token).transfer(destination, _amount);
        return _amount;
    }

function pricePerShare() public view returns (uint256) {
        uint256 balance = ERC20(token).balanceOf(address(this));
        if (balance == 0) return 1e18;
        return (balance * 1e18) / totalSupply;
    }

function updateShares() external {
        uint256 balance = ERC20(token).balanceOf(address(this));
        TestERC20(token).mint(address(this), balance / 10);
    }

function totalAssets() public view returns (uint256) {
        return ERC20(token).balanceOf(address(this));
    }

function _mint(address account, uint256 amount) internal override {
        balanceOf[account] = balanceOf[account] + amount;
        totalSupply += amount;
        emit Transfer(address(0), account, amount);
    }

function _burn(address account, uint256 amount) internal override {
        balanceOf[account] = balanceOf[account] - amount;
        totalSupply -= amount;
        emit Transfer(account, address(0), amount);
    }

function encodeTimestamp(uint256 timestamp)
        external
        returns (string memory)
    {
        // Will encode and store the result
        DateString.timestampToDateString(timestamp, testString);
        // We load and return the result
        return testString;
    }

function encodePrefixTimestamp(string calldata prefix, uint256 timestamp)
        external
        returns (string memory)
    {
        // Will encode and store the result
        DateString.encodeAndWriteTimestamp(prefix, timestamp, testString);
        // We load and return the result
        return testString;
    }

function mint(
        uint256 _amount,
        IERC20 _underlying,
        uint256 _expiration,
        address _position
    ) external payable notFrozen() {
        // If the underlying token matches this predefined 'ETH token'
        // then we create weth for the user and go from there
        if (address(_underlying) == _ETH_CONSTANT) {
            // Check that the amount matches the amount provided
            require(msg.value == _amount, "Incorrect amount provided");
            // Create weth from the provided eth
            // NOTE - This can be made slightly cheaper by depositing 1 wei into this
            //        contract address on weth.
            weth.deposit{ value: msg.value }();
            weth.transfer(address(_position), _amount);
            // Proceed to internal minting steps
            _mint(_expiration, _position);
        } else {
            // Move the user's funds to the wrapped position contract
            _underlying.transferFrom(msg.sender, address(_position), _amount);
            // Proceed to internal minting steps
            _mint(_expiration, _position);
        }
    }

function withdraw(uint256 wad) public {
        require(balanceOf[msg.sender] >= wad, "INSUFFICIENT_BALANCE");
        balanceOf[msg.sender] -= wad;
        msg.sender.transfer(wad);
        emit Withdrawal(msg.sender, wad);
    }

function getTotalTokens() external view returns (uint256) {
        return _tokens.length();
    }

function getTokens(uint256 start, uint256 end) external view returns (address[] memory) {
        require((end >= start) && (end - start) <= _tokens.length(), "OUT_OF_BOUNDS");

        address[] memory token = new address[](end - start);
        for (uint256 i = 0; i < token.length; ++i) {
            token[i] = _tokens.at(i + start);
        }

        return token;
    }

function create(
        address admin,
        string memory name,
        string memory symbol,
        uint8 decimals
    ) external returns (address) {
        bytes memory creationCode = abi.encodePacked(
            type(TestToken).creationCode,
            abi.encode(admin, name, symbol, decimals)
        );

        address expectedToken = Create2.computeAddress(0, keccak256(creationCode));

        if (expectedToken.isContract()) {
            return expectedToken;
        } else {
            address token = Create2.deploy(0, 0, creationCode);
            assert(token == expectedToken);

            _tokens.add(token);
            emit TokenCreated(token);

            return token;
        }
    }

