function _onInitializePool(
        bytes32,
        address,
        address,
        bytes memory userData
    ) internal override returns (uint256, uint256[] memory) {
        StablePool.JoinKind kind = userData.joinKind();
        require(kind == StablePool.JoinKind.INIT, "UNINITIALIZED");

        uint256[] memory amountsIn = userData.initialAmountsIn();
        InputHelpers.ensureInputLengthMatch(amountsIn.length, _totalTokens);
        _upscaleArray(amountsIn, _scalingFactors());

        uint256 invariantAfterJoin = StableMath._invariant(_amp, amountsIn);
        uint256 bptAmountOut = invariantAfterJoin;

        _lastInvariant = invariantAfterJoin;

        return (bptAmountOut, amountsIn);
    }

function _addSwapFee(uint256 amount) internal view returns (uint256) {
        // This returns amount + fees, so we round up (favoring fees).
        return amount.divUp(FixedPoint.ONE.sub(_swapFee));
    }

function _upscaleArray(uint256[] memory amount, uint256[] memory scalingFactors) internal view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            amount[i] = Math.mul(amount[i], scalingFactors[i]);
        }
    }

function _downscaleDownArray(uint256[] memory amount, uint256[] memory scalingFactors) internal view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            amount[i] = Math.divDown(amount[i], scalingFactors[i]);
        }
    }

function _downscaleUpArray(uint256[] memory amount, uint256[] memory scalingFactors) internal view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            amount[i] = Math.divUp(amount[i], scalingFactors[i]);
        }
    }

function _onSwapGivenIn(
        IPoolSwapStructs.SwapRequestGivenIn memory swapRequest,
        uint256[] memory balances,
        uint256 indexIn,
        uint256 indexOut
    ) internal view override returns (uint256) {
        return StableMath._outGivenIn(_amp, balances, indexIn, indexOut, swapRequest.amountIn);
    }

function _onSwapGivenOut(
        IPoolSwapStructs.SwapRequestGivenOut memory swapRequest,
        uint256[] memory balances,
        uint256 indexIn,
        uint256 indexOut
    ) internal view override returns (uint256) {
        return StableMath._inGivenOut(_amp, balances, indexIn, indexOut, swapRequest.amountOut);
    }

function _getDueProtocolFeeAmounts(
        uint256[] memory currentBalances,
        uint256 previousInvariant,
        uint256 protocolSwapFeePercentage
    ) private view returns (uint256[] memory) {
        // Instead of paying the protocol swap fee in all tokens proportionally, we will pay it in a single one. This
        // will reduce gas costs for single asset joins and exits, as at most only two Pool balances will change (the
        // token joined/exited, and the token in which fees will be paid).

        // The token fees is paid in is chosen pseudo-randomly, with the hope to achieve a uniform distribution across
        // multiple joins and exits. This pseudo-randomness being manipulated is not an issue.
        uint256 chosenTokenIndex = UnsafeRandom.rand(_totalTokens);

        // Initialize with zeros
        uint256[] memory dueProtocolFeeAmounts = new uint256[](_totalTokens);
        // Set the fee to pay in the selected token
        dueProtocolFeeAmounts[chosenTokenIndex] = StableMath._calculateDueTokenProtocolSwapFee(
            _amp,
            currentBalances,
            previousInvariant,
            chosenTokenIndex,
            protocolSwapFeePercentage
        );

        return dueProtocolFeeAmounts;
    }

function _invariantAfterJoin(uint256[] memory currentBalances, uint256[] memory amountsIn)
        private
        view
        returns (uint256)
    {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            currentBalances[i] = currentBalances[i].add(amountsIn[i]);
        }

        return StableMath._invariant(_amp, currentBalances);
    }

function _invariantAfterExit(uint256[] memory currentBalances, uint256[] memory amountsOut)
        private
        view
        returns (uint256)
    {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            currentBalances[i] = currentBalances[i].sub(amountsOut[i]);
        }

        return StableMath._invariant(_amp, currentBalances);
    }

function _scalingFactors() internal view returns (uint256[] memory) {
        uint256[] memory scalingFactors = new uint256[](_totalTokens);

        // prettier-ignore
        {
            if (_totalTokens > 0) { scalingFactors[0] = _scalingFactor0; } else { return scalingFactors; }
            if (_totalTokens > 1) { scalingFactors[1] = _scalingFactor1; } else { return scalingFactors; }
            if (_totalTokens > 2) { scalingFactors[2] = _scalingFactor2; } else { return scalingFactors; }
            if (_totalTokens > 3) { scalingFactors[3] = _scalingFactor3; } else { return scalingFactors; }
            if (_totalTokens > 4) { scalingFactors[4] = _scalingFactor4; } else { return scalingFactors; }
            if (_totalTokens > 5) { scalingFactors[5] = _scalingFactor5; } else { return scalingFactors; }
            if (_totalTokens > 6) { scalingFactors[6] = _scalingFactor6; } else { return scalingFactors; }
            if (_totalTokens > 7) { scalingFactors[7] = _scalingFactor7; } else { return scalingFactors; }
            if (_totalTokens > 8) { scalingFactors[8] = _scalingFactor8; } else { return scalingFactors; }
            if (_totalTokens > 9) { scalingFactors[9] = _scalingFactor9; } else { return scalingFactors; }
            if (_totalTokens > 10) { scalingFactors[10] = _scalingFactor10; } else { return scalingFactors; }
            if (_totalTokens > 11) { scalingFactors[11] = _scalingFactor11; } else { return scalingFactors; }
            if (_totalTokens > 12) { scalingFactors[12] = _scalingFactor12; } else { return scalingFactors; }
            if (_totalTokens > 13) { scalingFactors[13] = _scalingFactor13; } else { return scalingFactors; }
            if (_totalTokens > 14) { scalingFactors[14] = _scalingFactor14; } else { return scalingFactors; }
            if (_totalTokens > 15) { scalingFactors[15] = _scalingFactor15; } else { return scalingFactors; }
        }

        return scalingFactors;
    }

function _onInitializePool(
        bytes32,
        address,
        address,
        bytes memory userData
    ) internal override returns (uint256, uint256[] memory) {
        WeightedPool.JoinKind kind = userData.joinKind();
        require(kind == WeightedPool.JoinKind.INIT, "UNINITIALIZED");

        uint256[] memory amountsIn = userData.initialAmountsIn();
        require(amountsIn.length == _totalTokens, "ERR_AMOUNTS_IN_LENGTH");
        _upscaleArray(amountsIn, _scalingFactors());

        uint256[] memory normalizedWeights = _normalizedWeights();

        uint256 invariantAfterJoin = WeightedMath._invariant(normalizedWeights, amountsIn);

        uint256 bptAmountOut = Math.mul(invariantAfterJoin, _totalTokens);

        _lastInvariant = invariantAfterJoin;

        return (bptAmountOut, amountsIn);
    }

function _onJoinPool(
        bytes32,
        address,
        address,
        uint256[] memory currentBalances,
        uint256,
        uint256 protocolSwapFeePercentage,
        bytes memory userData
    )
        internal
        override
        returns (
            uint256,
            uint256[] memory,
            uint256[] memory
        )
    {
        uint256[] memory normalizedWeights = _normalizedWeights();

        // Due protocol swap fees are computed by measuring the growth of the invariant from the previous join or exit
        // event and now - the invariant's growth is due exclusively to swap fees.
        uint256 invariantBeforeJoin = WeightedMath._invariant(normalizedWeights, currentBalances);
        uint256[] memory dueProtocolFeeAmounts = _getDueProtocolFeeAmounts(
            currentBalances,
            normalizedWeights,
            _lastInvariant,
            invariantBeforeJoin,
            protocolSwapFeePercentage
        );

        // Update current balances by subtracting the protocol due fee amounts
        _subtractToCurrentBalances(currentBalances, dueProtocolFeeAmounts);
        (uint256 bptAmountOut, uint256[] memory amountsIn) = _doJoin(currentBalances, normalizedWeights, userData);

        // Update the invariant with the balances the Pool will have after the join, in order to compute the due
        // protocol swap fees in future joins and exits.
        _lastInvariant = _invariantAfterJoin(currentBalances, amountsIn, normalizedWeights);

        return (bptAmountOut, amountsIn, dueProtocolFeeAmounts);
    }

function _onExitPool(
        bytes32,
        address,
        address,
        uint256[] memory currentBalances,
        uint256,
        uint256 protocolSwapFeePercentage,
        bytes memory userData
    )
        internal
        override
        returns (
            uint256,
            uint256[] memory,
            uint256[] memory
        )
    {
        uint256[] memory normalizedWeights = _normalizedWeights();

        // Due protocol swap fees are computed by measuring the growth of the invariant from the previous join or exit
        // event and now - the invariant's growth is due exclusively to swap fees.
        uint256 invariantBeforeExit = WeightedMath._invariant(normalizedWeights, currentBalances);
        uint256[] memory dueProtocolFeeAmounts = _getDueProtocolFeeAmounts(
            currentBalances,
            normalizedWeights,
            _lastInvariant,
            invariantBeforeExit,
            protocolSwapFeePercentage
        );

        // Update current balances by subtracting the protocol due fee amounts
        _subtractToCurrentBalances(currentBalances, dueProtocolFeeAmounts);
        (uint256 bptAmountIn, uint256[] memory amountsOut) = _doExit(currentBalances, normalizedWeights, userData);

        // Update the invariant with the balances the Pool will have after the exit, in order to compute the due
        // protocol swap fees in future joins and exits.
        _lastInvariant = _invariantAfterExit(currentBalances, amountsOut, normalizedWeights);

        return (bptAmountIn, amountsOut, dueProtocolFeeAmounts);
    }

function _addSwapFee(uint256 amount) internal view returns (uint256) {
        // This returns amount + fees, so we round up (favoring fees).
        return amount.divUp(FixedPoint.ONE.sub(_swapFee));
    }

function _upscaleArray(uint256[] memory amount, uint256[] memory scalingFactors) internal view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            amount[i] = Math.mul(amount[i], scalingFactors[i]);
        }
    }

function _downscaleDownArray(uint256[] memory amount, uint256[] memory scalingFactors) internal view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            amount[i] = Math.divDown(amount[i], scalingFactors[i]);
        }
    }

function _downscaleUpArray(uint256[] memory amount, uint256[] memory scalingFactors) internal view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            amount[i] = Math.divUp(amount[i], scalingFactors[i]);
        }
    }

function getInvariant() external view returns (uint256) {
        (, uint256[] memory balances) = _vault.getPoolTokens(_poolId);
        uint256[] memory normalizedWeights = _normalizedWeights();
        return WeightedMath._invariant(normalizedWeights, balances);
    }

function _joinExactTokensInForBPTOut(
        uint256[] memory currentBalances,
        uint256[] memory normalizedWeights,
        bytes memory userData
    ) private view returns (uint256, uint256[] memory) {
        (uint256[] memory amountsIn, uint256 minBPTAmountIn) = userData.exactTokensInForBptOut();
        require(amountsIn.length == _totalTokens, "ERR_AMOUNTS_IN_LENGTH");
        _upscaleArray(amountsIn, _scalingFactors());

        uint256 bptAmountOut = WeightedMath._exactTokensInForBPTOut(
            currentBalances,
            normalizedWeights,
            amountsIn,
            totalSupply(),
            _swapFee
        );

        require(bptAmountOut >= minBPTAmountIn, "BPT_OUT_MIN_AMOUNT");

        return (bptAmountOut, amountsIn);
    }

function _joinTokenInForExactBPTOut(
        uint256[] memory currentBalances,
        uint256[] memory normalizedWeights,
        bytes memory userData
    ) private view returns (uint256, uint256[] memory) {
        (uint256 bptAmountOut, uint256 tokenIndex) = userData.tokenInForExactBptOut();

        uint256[] memory amountsIn = new uint256[](_totalTokens);
        amountsIn[tokenIndex] = WeightedMath._tokenInForExactBPTOut(
            currentBalances[tokenIndex],
            normalizedWeights[tokenIndex],
            bptAmountOut,
            totalSupply(),
            _swapFee
        );

        return (bptAmountOut, amountsIn);
    }

function _exitExactBPTInForOneTokenOut(
        uint256[] memory normalizedWeights,
        uint256[] memory currentBalances,
        bytes memory userData
    ) private view returns (uint256, uint256[] memory) {
        (uint256 bptAmountIn, uint256 tokenIndex) = userData.exactBptInForOneTokenOut();
        require(tokenIndex < _totalTokens, "OUT_OF_BOUNDS");

        // We exit in a single token, so we initialize amountsOut with zeros
        uint256[] memory amountsOut = new uint256[](_totalTokens);

        // And then assign the result to the selected token
        amountsOut[tokenIndex] = WeightedMath._exactBPTInForTokenOut(
            currentBalances[tokenIndex],
            normalizedWeights[tokenIndex],
            bptAmountIn,
            totalSupply(),
            _swapFee
        );

        return (bptAmountIn, amountsOut);
    }

function _exitBPTInForExactTokensOut(
        uint256[] memory normalizedWeights,
        uint256[] memory currentBalances,
        bytes memory userData
    ) private view returns (uint256, uint256[] memory) {
        (uint256[] memory amountsOut, uint256 maxBPTAmountIn) = userData.bptInForExactTokensOut();
        InputHelpers.ensureInputLengthMatch(amountsOut.length, _totalTokens);
        _upscaleArray(amountsOut, _scalingFactors());

        uint256 bptAmountIn = WeightedMath._bptInForExactTokensOut(
            currentBalances,
            normalizedWeights,
            amountsOut,
            totalSupply(),
            _swapFee
        );
        require(bptAmountIn <= maxBPTAmountIn, "BPT_IN_MAX_AMOUNT");

        return (bptAmountIn, amountsOut);
    }

function _getDueProtocolFeeAmounts(
        uint256[] memory currentBalances,
        uint256[] memory normalizedWeights,
        uint256 previousInvariant,
        uint256 currentInvariant,
        uint256 protocolSwapFeePercentage
    ) private view returns (uint256[] memory) {
        // Instead of paying the protocol swap fee in all tokens proportionally, we will pay it in a single one. This
        // will reduce gas costs for single asset joins and exits, as at most only two Pool balances will change (the
        // token joined/exited, and the token in which fees will be paid).

        // The token fees is paid in is chosen pseudo-randomly, with the hope to achieve a uniform distribution across
        // multiple joins and exits. This pseudo-randomness being manipulated is not an issue.
        uint256 chosenTokenIndex = UnsafeRandom.rand(_totalTokens);

        // Initialize with zeros
        uint256[] memory dueProtocolFeeAmounts = new uint256[](_totalTokens);

        // Set the fee to pay in the selected token
        dueProtocolFeeAmounts[chosenTokenIndex] = WeightedMath._calculateDueTokenProtocolSwapFee(
            currentBalances[chosenTokenIndex],
            normalizedWeights[chosenTokenIndex],
            previousInvariant,
            currentInvariant,
            protocolSwapFeePercentage
        );

        return dueProtocolFeeAmounts;
    }

function _invariantAfterJoin(
        uint256[] memory currentBalances,
        uint256[] memory amountsOut,
        uint256[] memory normalizedWeights
    ) private view returns (uint256) {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            currentBalances[i] = currentBalances[i].add(amountsOut[i]);
        }

        return WeightedMath._invariant(normalizedWeights, currentBalances);
    }

function _normalizedWeights() internal view returns (uint256[] memory) {
        uint256[] memory normalizedWeights = new uint256[](_totalTokens);

        // prettier-ignore
        {
            if (_totalTokens > 0) { normalizedWeights[0] = _normalizedWeight0; } else { return normalizedWeights; }
            if (_totalTokens > 1) { normalizedWeights[1] = _normalizedWeight1; } else { return normalizedWeights; }
            if (_totalTokens > 2) { normalizedWeights[2] = _normalizedWeight2; } else { return normalizedWeights; }
            if (_totalTokens > 3) { normalizedWeights[3] = _normalizedWeight3; } else { return normalizedWeights; }
            if (_totalTokens > 4) { normalizedWeights[4] = _normalizedWeight4; } else { return normalizedWeights; }
            if (_totalTokens > 5) { normalizedWeights[5] = _normalizedWeight5; } else { return normalizedWeights; }
            if (_totalTokens > 6) { normalizedWeights[6] = _normalizedWeight6; } else { return normalizedWeights; }
            if (_totalTokens > 7) { normalizedWeights[7] = _normalizedWeight7; } else { return normalizedWeights; }
            if (_totalTokens > 8) { normalizedWeights[8] = _normalizedWeight8; } else { return normalizedWeights; }
            if (_totalTokens > 9) { normalizedWeights[9] = _normalizedWeight9; } else { return normalizedWeights; }
            if (_totalTokens > 10) { normalizedWeights[10] = _normalizedWeight10; } else { return normalizedWeights; }
            if (_totalTokens > 11) { normalizedWeights[11] = _normalizedWeight11; } else { return normalizedWeights; }
            if (_totalTokens > 12) { normalizedWeights[12] = _normalizedWeight12; } else { return normalizedWeights; }
            if (_totalTokens > 13) { normalizedWeights[13] = _normalizedWeight13; } else { return normalizedWeights; }
            if (_totalTokens > 14) { normalizedWeights[14] = _normalizedWeight14; } else { return normalizedWeights; }
            if (_totalTokens > 15) { normalizedWeights[15] = _normalizedWeight15; } else { return normalizedWeights; }
        }

        return normalizedWeights;
    }

function _scalingFactors() internal view returns (uint256[] memory) {
        uint256[] memory scalingFactors = new uint256[](_totalTokens);

        // prettier-ignore
        {
            if (_totalTokens > 0) { scalingFactors[0] = _scalingFactor0; } else { return scalingFactors; }
            if (_totalTokens > 1) { scalingFactors[1] = _scalingFactor1; } else { return scalingFactors; }
            if (_totalTokens > 2) { scalingFactors[2] = _scalingFactor2; } else { return scalingFactors; }
            if (_totalTokens > 3) { scalingFactors[3] = _scalingFactor3; } else { return scalingFactors; }
            if (_totalTokens > 4) { scalingFactors[4] = _scalingFactor4; } else { return scalingFactors; }
            if (_totalTokens > 5) { scalingFactors[5] = _scalingFactor5; } else { return scalingFactors; }
            if (_totalTokens > 6) { scalingFactors[6] = _scalingFactor6; } else { return scalingFactors; }
            if (_totalTokens > 7) { scalingFactors[7] = _scalingFactor7; } else { return scalingFactors; }
            if (_totalTokens > 8) { scalingFactors[8] = _scalingFactor8; } else { return scalingFactors; }
            if (_totalTokens > 9) { scalingFactors[9] = _scalingFactor9; } else { return scalingFactors; }
            if (_totalTokens > 10) { scalingFactors[10] = _scalingFactor10; } else { return scalingFactors; }
            if (_totalTokens > 11) { scalingFactors[11] = _scalingFactor11; } else { return scalingFactors; }
            if (_totalTokens > 12) { scalingFactors[12] = _scalingFactor12; } else { return scalingFactors; }
            if (_totalTokens > 13) { scalingFactors[13] = _scalingFactor13; } else { return scalingFactors; }
            if (_totalTokens > 14) { scalingFactors[14] = _scalingFactor14; } else { return scalingFactors; }
            if (_totalTokens > 15) { scalingFactors[15] = _scalingFactor15; } else { return scalingFactors; }
        }

        return scalingFactors;
    }

function _subtractToCurrentBalances(uint256[] memory currentBalances, uint256[] memory amounts) private view {
        for (uint256 i = 0; i < _totalTokens; ++i) {
            currentBalances[i] = currentBalances[i].sub(amounts[i]);
        }
    }

function totalSupply() public view override returns (uint256) {
        return _totalSupply;
    }

function _registerGeneralPoolTokens(bytes32 poolId, IERC20[] memory tokens) internal {
        EnumerableMap.IERC20ToBytes32Map storage poolBalances = _generalPoolsBalances[poolId];

        for (uint256 i = 0; i < tokens.length; ++i) {
            IERC20 token = tokens[i];
            require(token != IERC20(0), "ZERO_ADDRESS_TOKEN");
            bool added = poolBalances.set(token, 0);
            require(added, "TOKEN_ALREADY_REGISTERED");
            // No need to delete the balance entries, since they already are zero
        }
    }

function _deregisterGeneralPoolTokens(bytes32 poolId, IERC20[] memory tokens) internal {
        EnumerableMap.IERC20ToBytes32Map storage poolBalances = _generalPoolsBalances[poolId];

        for (uint256 i = 0; i < tokens.length; ++i) {
            IERC20 token = tokens[i];
            bytes32 currentBalance = _getGeneralPoolBalance(poolBalances, token);
            require(currentBalance.isZero(), "NONZERO_TOKEN_BALANCE");
            poolBalances.remove(token);
        }
    }

function _setGeneralPoolBalances(bytes32 poolId, bytes32[] memory balances) internal {
        EnumerableMap.IERC20ToBytes32Map storage poolBalances = _generalPoolsBalances[poolId];
        for (uint256 i = 0; i < balances.length; ++i) {
            // Note we assume all balances are properly ordered.
            // Thus, we can use `unchecked_setAt` to avoid one less storage read per call.
            poolBalances.unchecked_setAt(i, balances[i]);
        }
    }

function _updateGeneralPoolBalance(
        bytes32 poolId,
        IERC20 token,
        function(bytes32, uint256) returns (bytes32) mutation,
        uint256 amount
    ) internal {
        EnumerableMap.IERC20ToBytes32Map storage poolBalances = _generalPoolsBalances[poolId];
        bytes32 currentBalance = _getGeneralPoolBalance(poolBalances, token);
        poolBalances.set(token, mutation(currentBalance, amount));
    }

function _getGeneralPoolTokens(bytes32 poolId)
        internal
        view
        returns (IERC20[] memory tokens, bytes32[] memory balances)
    {
        EnumerableMap.IERC20ToBytes32Map storage poolBalances = _generalPoolsBalances[poolId];
        tokens = new IERC20[](poolBalances.length());
        balances = new bytes32[](tokens.length);

        for (uint256 i = 0; i < tokens.length; ++i) {
            // Because the iteration is bounded by `tokens.length` already fetched from the enumerable map,
            // we can use `unchecked_at` as we know `i` is a valid token index, saving storage reads.
            (IERC20 token, bytes32 balance) = poolBalances.unchecked_at(i);
            tokens[i] = token;
            balances[i] = balance;
        }
    }

function _isGeneralPoolTokenRegistered(bytes32 poolId, IERC20 token) internal view returns (bool) {
        EnumerableMap.IERC20ToBytes32Map storage poolBalances = _generalPoolsBalances[poolId];
        return poolBalances.contains(token);
    }

function _registerMinimalSwapInfoPoolTokens(bytes32 poolId, IERC20[] memory tokens) internal {
        EnumerableSet.AddressSet storage poolTokens = _minimalSwapInfoPoolsTokens[poolId];

        for (uint256 i = 0; i < tokens.length; ++i) {
            IERC20 token = tokens[i];
            require(token != IERC20(0), "ZERO_ADDRESS_TOKEN");
            bool added = poolTokens.add(address(token));
            require(added, "TOKEN_ALREADY_REGISTERED");
        }
    }

function _deregisterMinimalSwapInfoPoolTokens(bytes32 poolId, IERC20[] memory tokens) internal {
        EnumerableSet.AddressSet storage poolTokens = _minimalSwapInfoPoolsTokens[poolId];

        for (uint256 i = 0; i < tokens.length; ++i) {
            IERC20 token = tokens[i];
            require(_minimalSwapInfoPoolsBalances[poolId][token].isZero(), "NONZERO_TOKEN_BALANCE");
            bool removed = poolTokens.remove(address(token));
            require(removed, "TOKEN_NOT_REGISTERED");
            // No need to delete the balance entries, since they already are zero
        }
    }

function _getMinimalSwapInfoPoolTokens(bytes32 poolId)
        internal
        view
        returns (IERC20[] memory tokens, bytes32[] memory balances)
    {
        EnumerableSet.AddressSet storage poolTokens = _minimalSwapInfoPoolsTokens[poolId];
        tokens = new IERC20[](poolTokens.length());
        balances = new bytes32[](tokens.length);

        for (uint256 i = 0; i < tokens.length; ++i) {
            IERC20 token = IERC20(poolTokens.at(i));
            tokens[i] = token;
            balances[i] = _minimalSwapInfoPoolsBalances[poolId][token];
        }
    }

function _isMinimalSwapInfoPoolTokenRegistered(bytes32 poolId, IERC20 token) internal view returns (bool) {
        EnumerableSet.AddressSet storage poolTokens = _minimalSwapInfoPoolsTokens[poolId];
        return poolTokens.contains(address(token));
    }

function _setTwoTokenPoolCashBalances(
        bytes32 poolId,
        IERC20 tokenA,
        bytes32 balanceA,
        IERC20 tokenB,
        bytes32 balanceB
    ) internal {
        bytes32 hash = _getTwoTokenPairHash(tokenA, tokenB);
        TwoTokenPoolBalances storage poolBalances = _twoTokenPoolTokens[poolId].balances[hash];
        poolBalances.sharedCash = BalanceAllocation.toSharedCash(balanceA, balanceB);
    }

function _getTwoTokenPoolSharedBalances(
        bytes32 poolId,
        IERC20 tokenX,
        IERC20 tokenY
    )
        internal
        view
        returns (
            bytes32 balanceA,
            bytes32 balanceB,
            TwoTokenPoolBalances storage poolBalances
        )
    {
        (IERC20 tokenA, IERC20 tokenB) = _sortTwoTokens(tokenX, tokenY);
        bytes32 pairHash = _getTwoTokenPairHash(tokenA, tokenB);
        poolBalances = _twoTokenPoolTokens[poolId].balances[pairHash];

        bytes32 sharedCash = poolBalances.sharedCash;
        bytes32 sharedManaged = poolBalances.sharedManaged;

        // Only registered tokens can have non-zero balances, so we can use this as a shortcut to avoid the
        // expensive _hasPoolTwoTokens check.
        bool exists = sharedCash.isNotZero() || sharedManaged.isNotZero() || _hasPoolTwoTokens(poolId, tokenA, tokenB);
        require(exists, "TOKEN_NOT_REGISTERED");

        balanceA = BalanceAllocation.fromSharedToBalanceA(sharedCash, sharedManaged);
        balanceB = BalanceAllocation.fromSharedToBalanceB(sharedCash, sharedManaged);
    }

function _getTwoTokenPoolBalances(bytes32 poolId)
        private
        view
        returns (
            TwoTokenPoolBalances storage poolBalances,
            IERC20 tokenA,
            bytes32 balanceA,
            IERC20 tokenB,
            bytes32 balanceB
        )
    {
        TwoTokenPoolTokens storage poolTokens = _twoTokenPoolTokens[poolId];
        tokenA = poolTokens.tokenA;
        tokenB = poolTokens.tokenB;

        bytes32 pairHash = _getTwoTokenPairHash(tokenA, tokenB);
        poolBalances = poolTokens.balances[pairHash];

        bytes32 sharedCash = poolBalances.sharedCash;
        bytes32 sharedManaged = poolBalances.sharedManaged;

        balanceA = BalanceAllocation.fromSharedToBalanceA(sharedCash, sharedManaged);
        balanceB = BalanceAllocation.fromSharedToBalanceB(sharedCash, sharedManaged);
    }

function _hasPoolTwoTokens(
        bytes32 poolId,
        IERC20 tokenA,
        IERC20 tokenB
    ) internal view returns (bool) {
        TwoTokenPoolTokens storage poolTokens = _twoTokenPoolTokens[poolId];
        return poolTokens.tokenA == tokenA && tokenB == poolTokens.tokenB;
    }

function orderRemainingInCheckAllowanceAndBalance(
        uint256 _orderId
        ) external view
        returns (uint256)
    {
        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];
        if (!orderCanBeFilled(_orderId)) return 0;
        if (order.deposit) return state.remainingIn;

        return Math.min(
            state.remainingIn,
            Math.min(
                IERC20(order.tokenIn).balanceOf(order.poster),
                IERC20(order.tokenIn).allowance(order.poster,address(this))
                )
            );
    }

function cancelOrder(
        uint256 _orderId
        ) external
    {
        require(_orderId != 0 && _orderId <= orderCount, "Crossroad: Invalid order");

        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];

        require(order.poster == msg.sender, "Crossroad: Can't cancel another poster's order");
        require(state.status == OrderStatus.OPEN, "Crossroad: Order is not open");

        // mark as cancelled
        state.status = OrderStatus.CANCELLED;
        // remove from record keeping
        recordCloseOrder(order.poster, _orderId);

        emit OrderCancelled(_orderId);

        // update amounts
        uint256 _amountIn = state.remainingIn;
        uint256 _amountReward = state.remainingReward;

        state.remainingIn = 0;
        state.remainingOut = 0;
        state.remainingReward = 0;

        // refund any remaining deposit
        if (order.deposit)
        {
            if (order.tokenIn == address(0))
            {
                TransferHelper.safeTransferETH(order.poster,_amountIn);
            }
            else
            {
                IERC20(order.tokenIn).safeTransfer(order.poster,_amountIn);
            }
        }

        // refund any remaining reward
        IERC20(order.tokenReward).safeTransfer(order.poster,_amountReward);
    }

function fillOrderOutToken(
        uint256 _orderId,
        uint256 _amountOut,
        address _to,
        bool _callback,
        bytes calldata _callbackData
        ) external
    {
        require(_orderId != 0 && _orderId <= orderCount, "Crossroad: Invalid order");

        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];

        require(address(0) != order.tokenOut, "Crossroad: Wrong function call");

        uint256 _amountIn;
        uint256 _amountReward;
        (_amountIn,_amountOut,_amountReward) = processFillOrder(_orderId,order,state,_amountOut);

        // transfer token in to caller
        transferTokenInToCaller(_orderId,_amountIn,_to);

        // transfer reward to caller
        IERC20(order.tokenReward).safeTransfer(_to,_amountReward);

        // crossroad callback
        if (_callback)
        {
            ICrossroadCallee(_to).crossroadCall(
                msg.sender,
                _amountIn,
                _amountOut,
                _amountReward,
                _callbackData
                );
        }

        // transfer token out to poster
        IERC20(order.tokenOut).safeTransferFrom(_to,order.poster,_amountOut);
    }

function fillOrderOutBnb(
        uint256 _orderId,
        uint256 _amountOut,
        address _to,
        bool _callback,
        bytes calldata _callbackData
        ) external payable
    {
        require(_orderId != 0 && _orderId <= orderCount, "Crossroad: Invalid order");

        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];

        require(address(0) == order.tokenOut, "Crossroad: Wrong function call");

        uint256 _amountIn;
        uint256 _amountReward;
        (_amountIn,_amountOut,_amountReward) = processFillOrder(_orderId,order,state,_amountOut);

        // transfer token in to caller
        transferTokenInToCaller(_orderId,_amountIn,_to);

        // transfer reward to caller
        IERC20(order.tokenReward).safeTransfer(_to,_amountReward);

        // crossroad callback
        uint256 _totalValue = msg.value;
        if (_callback)
        {
            uint256 _prevBalanceBnb = address(this).balance;
            ICrossroadCallee(_to).crossroadCall(
                msg.sender,
                _amountIn,
                _amountOut,
                _amountReward,
                _callbackData
                );
            uint256 _currBalanceBnb = address(this).balance;

            _totalValue += _currBalanceBnb - _prevBalanceBnb;
        }
        require(_amountOut <= _totalValue, "Crossroad: Insufficient BNB paid");

        // refund excess BNB
        TransferHelper.safeTransferETH(msg.sender,_totalValue-_amountOut);

        // transfer token out to poster
        TransferHelper.safeTransferETH(order.poster,_amountOut);
    }

function payFee(
        uint256 _rewardAmount
        ) internal
    {
        IERC20(feeToken).safeTransferFrom(msg.sender,projectAddress,feeAmount);
        IERC20(feeToken).safeTransferFrom(msg.sender,address(this),_rewardAmount);
    }

function buyFee(
        uint256 _bnbAmount,
        uint256 _rewardAmount
        ) internal
    {
        uint256 _prevRewardBalance = IERC20(feeToken).balanceOf(address(this));

        // buy fee and reward
        // transfer fee to project
        uint256 _feeAndRewardAmount = feeAmount + _rewardAmount;
        ITokenAutoBuyer(feeAutoBuyer).buyTokenFixed{value: _bnbAmount}(_feeAndRewardAmount,address(this),msg.sender);
        IERC20(feeToken).safeTransfer(projectAddress,feeAmount);

        require(_prevRewardBalance + _rewardAmount <= IERC20(feeToken).balanceOf(address(this)), "Crossroad: Fee auto buyer error");
    }

function transferTokenInToCaller(
        uint256 _orderId,
        uint256 _amountIn,
        address _to
        ) internal
    {
        Order storage _order = orders[_orderId];

        if (_order.deposit)
        {
            if (_order.tokenIn == address(0))
            {
                TransferHelper.safeTransferETH(_to,_amountIn);
            }
            else
            {
                IERC20(_order.tokenIn).safeTransfer(_to,_amountIn);
            }
        }
        else
        {
            IERC20(_order.tokenIn).safeTransferFrom(_order.poster,_to,_amountIn);
        }
    }

function orderCanBeFilled(
        uint256 _orderId
        ) public view
        returns (bool)
    {
        return
            block.timestamp < orders[_orderId].expiryTime &&
            orderStates[_orderId].status == OrderStatus.OPEN
            ;
    }

function recordCloseOrder(
        address _poster,
        uint256 _orderId
        ) internal
    {
        // update global orders
        {
            openOrderCount -= 1;

            uint256 _nextOpenOrderId = nextOpenOrderIds[_orderId];
            uint256 _prevOpenOrderId = prevOpenOrderIds[_orderId];

            nextOpenOrderIds[_prevOpenOrderId] = _nextOpenOrderId;
            prevOpenOrderIds[_nextOpenOrderId] = _prevOpenOrderId;
        }

        // update poster orders
        {
            posterOpenOrderCounts[_poster] -= 1;

            mapping(uint256 => uint256) storage _nextOpenOrderIds = posterNextOpenOrderIds[_poster];
            mapping(uint256 => uint256) storage _prevOpenOrderIds = posterPrevOpenOrderIds[_poster];

            uint256 _nextOpenOrderId = _nextOpenOrderIds[_orderId];
            uint256 _prevOpenOrderId = _prevOpenOrderIds[_orderId];

            _nextOpenOrderIds[_prevOpenOrderId] = _nextOpenOrderId;
            _prevOpenOrderIds[_nextOpenOrderId] = _prevOpenOrderId;
        }
    }

function addLiquidityBnb(
        address _factory,
        address _tokenLp,
        address _token,
        uint _amountTokenDesired,
        uint _amountBnbDesired,
        uint _amountTokenMin,
        uint _amountBnbMin,
        address _to
        ) external payable returns (uint amountToken_, uint amountBnb_, uint liquidity_)
    {
        require(_amountBnbDesired <= msg.value, "LiquidityProxy: Insufficient BNB");

        factoryEnsurePairExistsInner(_factory,_token,WBNB);

        (amountToken_, amountBnb_) = getAddLiquidityAmountsInner(
            _tokenLp,
            _token,
            WBNB,
            _amountTokenDesired,
            _amountBnbDesired,
            _amountTokenMin,
            _amountBnbMin
            );
        IERC20(_token).safeTransferFrom(msg.sender, _tokenLp, amountToken_);
        IWETH(WBNB).deposit{value: amountBnb_}();
        IERC20(WBNB).safeTransfer(_tokenLp, amountBnb_);
        liquidity_ = IUniswapPool(_tokenLp).mint(_to);
        // refund excess bnb
        if (_amountBnbDesired > amountBnb_) TransferHelper.safeTransferETH(msg.sender, _amountBnbDesired - amountBnb_);
    }

function removeLiquidityBnb(
        address _tokenLp,
        address _token,
        uint _liquidity,
        uint _amountTokenMin,
        uint _amountBnbMin,
        address _to
        ) external payable returns (uint amountToken_, uint amountBnb_)
    {
        (amountToken_, amountBnb_) = removeLiquidity(
            _tokenLp,
            _token,
            WBNB,
            _liquidity,
            _amountTokenMin,
            _amountBnbMin,
            address(this)
            );
        IERC20(_token).safeTransfer(_to, amountToken_);
        IWETH(WBNB).withdraw(amountBnb_);
        TransferHelper.safeTransferETH(_to, amountBnb_);
    }

function removeLiquidity(uint256 amount, address to)
        external
        override
        whenNotPaused // T:[PS-4]
        nonReentrant
        returns (uint256)
    {
        uint256 underlyingTokensAmount = fromDiesel(amount); // T:[PS-3, 8]

        uint256 amountSent = underlyingTokensAmount.percentMul(
            withdrawMultiplier
        );

        IERC20(underlyingToken).safeTransfer(to, amountSent); // T:[PS-3, 34]
        IERC20(underlyingToken).safeTransfer(
            treasuryAddress,
            underlyingTokensAmount.percentMul(withdrawFee)
        ); // T:[PS-3, 34]
        DieselToken(dieselToken).burn(msg.sender, amount); // T:[PS-3, 8]

        _expectedLiquidityLU = _expectedLiquidityLU.sub(underlyingTokensAmount); // T:[PS-3, 8]
        _updateBorrowRate(); // T:[PS-3,8 ]

        emit RemoveLiquidity(msg.sender, to, amount); // T:[PS-3, 8]

        return amountSent;
    }

function lendCreditAccount(uint256 borrowedAmount, address creditAccount)
        external
        override
        whenNotPaused // T:[PS-4]
    {
        require(
            creditManagersCanBorrow[msg.sender],
            Errors.POOL_CREDIT_MANAGERS_ONLY
        ); // T:[PS-12, 13]

        // Transfer funds to credit account
        IERC20(underlyingToken).safeTransfer(creditAccount, borrowedAmount); // T:[PS-14]

        // Update borrow Rate
        _updateBorrowRate(); // T:[PS-17]

        // Increase total borrowed amount
        totalBorrowed = totalBorrowed.add(borrowedAmount); // T:[PS-16]

        emit Borrow(msg.sender, creditAccount, borrowedAmount); // T:[PS-15]
    }

function repayCreditAccount(
        uint256 borrowedAmount,
        uint256 profit,
        uint256 loss
    )
        external
        override
        whenNotPaused // T:[PS-4]
    {
        require(
            creditManagersCanRepay[msg.sender],
            Errors.POOL_CREDIT_MANAGERS_ONLY
        ); // T:[PS-12]

        // For fee surplus we mint tokens for treasury
        if (profit > 0) {
            // T:[PS-22] provess that diesel rate will be the same within the margin of error
            DieselToken(dieselToken).mint(treasuryAddress, toDiesel(profit)); // T:[PS-21, 22]
            _expectedLiquidityLU = _expectedLiquidityLU.add(profit); // T:[PS-21, 22]
        }
        // If returned money < borrowed amount + interest accrued
        // it tries to compensate loss by burning diesel (LP) tokens
        // from treasury fund
        else {
            uint256 amountToBurn = toDiesel(loss); // T:[PS-19,20]

            uint256 treasuryBalance = DieselToken(dieselToken).balanceOf(
                treasuryAddress
            ); // T:[PS-19,20]

            if (treasuryBalance < amountToBurn) {
                amountToBurn = treasuryBalance;
                emit UncoveredLoss(
                    msg.sender,
                    loss.sub(fromDiesel(treasuryBalance))
                ); // T:[PS-23]
            }

            // If treasury has enough funds, it just burns needed amount
            // to keep diesel rate on the same level
            DieselToken(dieselToken).burn(treasuryAddress, amountToBurn); // T:[PS-19. 20]

            _expectedLiquidityLU = _expectedLiquidityLU.sub(loss); //T:[PS-19,20]
        }

        // Update available liquidity
        _updateBorrowRate(); // T:[PS-19, 20, 21]

        // Reduce total borrowed. Should be after _updateBorrowRate() for correct calculations
        totalBorrowed = totalBorrowed.sub(borrowedAmount); // T:[PS-19, 20]

        emit Repay(msg.sender, borrowedAmount, profit, loss); // T:[PS-18]
    }

