function _updateBorrowRate() internal {
        // Update total _expectedLiquidityLU

        _expectedLiquidityLU = expectedLiquidity(); // T:[PS-27]

        // Update cumulativeIndex
        _cumulativeIndex_RAY = calcLinearCumulative_RAY(); // T:[PS-27]

        // update borrow APY
        borrowAPY_RAY = interestRateModel.calcBorrowRate(
            _expectedLiquidityLU,
            availableLiquidity()
        ); // T:[PS-27]
        _timestampLU = block.timestamp; // T:[PS-27]
    }

function setWithdrawFee(uint256 fee)
        public
        configuratorOnly // T:[PS-9]
    {
        require(
            fee < Constants.MAX_WITHDRAW_FEE,
            Errors.POOL_INCORRECT_WITHDRAW_FEE
        ); // T:[PS-32]
        withdrawFee = fee; // T:[PS-33]
        withdrawMultiplier = PercentageMath.PERCENTAGE_FACTOR.sub(fee); // T:[PS-33]
    }

function expectedLiquidity() public view override returns (uint256) {
        // timeDifference = blockTime - previous timeStamp
        uint256 timeDifference = block.timestamp.sub(uint256(_timestampLU));

        //                                    currentBorrowRate * timeDifference
        //  interestAccrued = totalBorrow *  ------------------------------------
        //                                             SECONDS_PER_YEAR
        //
        uint256 interestAccrued = totalBorrowed.rayMul(
            borrowAPY_RAY.mul(timeDifference).div(Constants.SECONDS_PER_YEAR)
        ); // T:[GM-1]

        return _expectedLiquidityLU.add(interestAccrued); // T:[PS-29]
    }

function calcLinearCumulative_RAY() public view override returns (uint256) {
        //solium-disable-next-line
        uint256 timeDifference = block.timestamp.sub(uint256(_timestampLU)); // T:[PS-28]

        return
            calcLinearIndex_RAY(
                _cumulativeIndex_RAY,
                borrowAPY_RAY,
                timeDifference
            ); // T:[PS-28]
    }

function allowContract(address targetContract, address adapter)
        external
        override
        configuratorOnly // T:[CF-1]
    {
        require(
            targetContract != address(0) && adapter != address(0),
            Errors.ZERO_ADDRESS_IS_NOT_ALLOWED
        ); // T:[CF-2]

        // Remove previous adapter from allowed list and set up new one
        allowedAdapters[contractToAdapter[targetContract]] = false; // T:[CF-10]
        allowedAdapters[adapter] = true; // T:[CF-9, 10]

        allowedContractsSet.add(targetContract);
        // SWC-135-Code With No Effects: L196
        contractToAdapter[targetContract] = adapter; // T:[CF-9, 10]

        emit ContractAllowed(targetContract, adapter); // T:[CF-12]
    }

function forbidContract(address targetContract)
        external
        override
        configuratorOnly // T:[CF-1]
    {
        require(
            targetContract != address(0),
            Errors.ZERO_ADDRESS_IS_NOT_ALLOWED
        ); // T:[CF-2]

        require(
            allowedContractsSet.remove(targetContract),
            Errors.CF_CONTRACT_IS_NOT_IN_ALLOWED_LIST
        ); // T:[CF-31]

        // Remove previous adapter from allowed list
        allowedAdapters[contractToAdapter[targetContract]] = false; // T:[CF-32]

        // Sets adapter to address(0), which means to forbid it usage
        contractToAdapter[targetContract] = address(0); // T:[CF-32]

        emit ContractForbidden(targetContract); // T:[CF-32]
    }

